"use client";
import { FormEvent, useState } from "react";
export default function PurchasesPage(){const [qty,setQty]=useState(1);const [cost,setCost]=useState(0);const [supplier,setSupplier]=useState("");const [message,setMessage]=useState("");function submit(e:FormEvent){e.preventDefault();setMessage("Purchase submitted successfully.");}return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><h1 className="text-2xl font-semibold">Purchases</h1><section className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">New Purchase Entry</h2><form onSubmit={submit} className="mt-5 grid gap-3 md:grid-cols-2"><select className="field"><option>Coca-Cola</option><option>Bread</option><option>Rice 5kg</option></select><input value={qty} onChange={e=>setQty(Number(e.target.value))} type="number" min="1" placeholder="Quantity" className="field"/><input value={cost} onChange={e=>setCost(Number(e.target.value))} type="number" placeholder="Cost price per unit" className="field"/><button className="rounded-xl bg-orange-500 px-4 py-3 font-semibold text-black">Add Item</button><input value={supplier} onChange={e=>setSupplier(e.target.value)} placeholder="Supplier (optional)" className="field"/><button type="submit" className="rounded-xl bg-orange-500 px-4 py-3 font-semibold text-black">Submit Purchase</button></form>{message&&<p className="mt-4 text-sm text-green-400">{message}</p>}</section><section className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">Purchase History</h2><div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{["ID","SUPPLIER","TOTAL COST","STATUS","CREATED","ACTION"].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody><tr><td colSpan={6} className="px-3 py-10 text-center text-white/30">No purchases yet</td></tr></tbody></table></div></section></div></main>}
